// Führt eine Lernaktion aus und meldet danach neue Pokale, erfüllte Missionen und Level-Aufstiege.
function reward(action){
  const xpBefore=xpTotal(state),keys=new Set(Object.keys(state.awards));
  const badges=[...new Set(action()||[])],xpAfter=xpTotal(state),messages=[];
  const quests=Object.keys(state.awards).filter(k=>k.startsWith('quest:')&&!keys.has(k)).map(k=>questById[k.slice(17)].title);
  if(level(xpAfter)>level(xpBefore))messages.push(`Level ${level(xpAfter)} erreicht · ${rankFor(xpAfter)}`);
  if(quests.length)messages.push('Mission erfüllt: '+quests.join(' · '));
  if(badges.length)messages.push('Pokal freigeschaltet: '+badges.map(id=>achievements.find(a=>a.id===id).title).join(' · '));
  if(messages.length)toast(messages.join(' — '));
  if(badges.length||level(xpAfter)>level(xpBefore))celebrate();
  return xpAfter-xpBefore;
}
function celebrate(){
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const box=document.createElement('div');box.className='confetti';box.setAttribute('aria-hidden','true');
  box.innerHTML=Array.from({length:36},(_,i)=>`<span style="left:${Math.random()*100}%;background:${['var(--lime)','var(--purple)','var(--green)','#e4cf8e'][i%4]};animation-delay:${Math.random()*.3}s;transform:rotate(${Math.random()*360}deg)"></span>`).join('');
  document.body.append(box);setTimeout(()=>box.remove(),1800);
}
function announceBadges(ids){if(ids.length)toast('Pokal freigeschaltet: '+ids.map(id=>achievements.find(a=>a.id===id).title).join(' · '));}
