function pathPage(){const w=weeks[selectedWeek-1],st=stats(state);return shell(`${pageHead('THEORETISCHE INFORMATIK · DEINE ROUTE BIS ZUR KLAUSUR','Dein Lernpfad','Neun Wochen, ein klares Ziel. Du bestimmst das Tempo.')}<div class="week-tabs" role="group" aria-label="Lernwoche auswählen">${weeks.map(w=>`<button data-action="week" data-week="${w.n}" class="${w.n===selectedWeek?'active':''}" aria-pressed="${w.n===selectedWeek}">Woche ${String(w.n).padStart(2,'0')}${w.n>1?' · Plan':''}</button>`).join('')}</div><section class="card week-intro"><div><span class="pill ${w.n===1?'':'gray'}">${w.n===1?'INTERAKTIV VERFÜGBAR':'GEPLANT · NOCH KEINE INTERAKTIVEN LEKTIONEN'}</span><h2 style="margin-top:15px">${w.title}</h2><p>${w.subtitle}</p><div class="week-meta"><span>${dateShort(w.start)} – ${dateShort(w.end)}2026</span><span>ca. ${w.hours} Stunden</span><span>${w.n===1?`${st.completed}/19 Lektionen abgeschlossen`:'Lernziel aus deinem Masterplan'}</span></div></div><span class="week-number" aria-hidden="true">${String(w.n).padStart(2,'0')}</span></section>${w.n===1?`${units.map((u,index)=>`<section class="card unit"><div class="unit-head">${icon(u.icon)}<div><h2>${String(index+1).padStart(2,'0')} · ${u.title}</h2><p>${u.subtitle}</p></div><span class="pill gray">${u.lessons.filter(id=>state.completed[id]).length}/${u.lessons.length}</span></div><div class="lesson-grid">${u.lessons.map(id=>{const l=lessonById[id],m=mastery(state,id);return `<a href="#lesson/${id}" class="lesson-tile"><span class="lesson-num ${state.completed[id]?'current':''}">${state.completed[id]?icon('check'):String(lessons.indexOf(l)+1).padStart(2,'0')}</span><div><h3>${l.title}</h3><p><span class="state-dot ${m}"></span>${m==='safe'?'Sicher':m==='learning'?'Im Aufbau':'Noch offen'} · ${l.minutes} Min. Einstieg</p></div></a>`;}).join('')}</div></section>`).join('')}<section class="card"><div class="card-title"><h2>Dein Wochenabschluss</h2>${icon('flag')}</div><p class="small muted">${w.goal} Für die Übungen und handschriftlichen Lösungswege sind weitere Arbeitsblöcke vorgesehen.</p><div class="inline-actions" style="margin-top:20px"><a href="#check" class="btn">Wochencheck öffnen ${icon('arrow')}</a><a href="#stats" class="btn ghost">Kompetenzen ansehen</a></div></section>`:`<section class="card planned"><div class="card-title"><h2>Das ist für Woche ${w.n} vorgesehen</h2>${icon('calendar')}</div><ol class="next-week-list">${w.topics.map(t=>`<li>${t}</li>`).join('')}</ol>${topicsOfWeek(w.n).length?`<p class="small" style="margin-top:14px"><strong>Schon zum Üben bereit:</strong></p><div class="inline-actions" style="margin-top:8px">${topicsOfWeek(w.n).map(t=>`<a class="btn secondary" href="#topic/${t.id}">${esc(t.title)} ${icon('chevron')}</a>`).join('')}</div>`:''}<div class="separator"></div><p class="small"><strong>Deine Aufgaben:</strong> ${w.tasks}</p><p class="small muted"><strong>Nachweis am Wochenende:</strong> ${w.goal}</p><div class="callout" style="margin-top:22px"><strong>Direkt ins Thementraining.</strong>Die ausführlichen Lektionen zu dieser Woche folgen. Kurzüberblicke, Verständnisfragen und Aufgaben zu den späteren Vorlesungskapiteln stehen bereits in der Trainingsarena bereit.</div><div class="inline-actions" style="margin-top:18px"><a href="#practice" class="btn">Trainingsarena öffnen →</a><a href="#exams" class="btn secondary">Probeklausuren</a></div><a href="#path" class="btn secondary" style="margin-top:20px" data-action="week" data-week="1">Zur interaktiven Woche 1 ${icon('arrow')}</a></section>`}<p class="help" style="margin-top:20px">„Abgeschlossen“: mindestens 80 % der Lektionsaufgaben ohne Hinweis. „Sicher“: zwei unterschiedliche Aufgaben an unterschiedlichen Tagen ohne Hilfe, ohne offene Fehler. Prozentziele sind eigene Trainingsziele.</p>`,'path');}
function lessonPage(id){const l=lessonById[id];if(!l)return notFound();state.lastLesson=id;persist();const qs=questions.filter(q=>q.lesson===id);return shell(`<a href="#path" class="back-link">${icon('back')} Zurück zum Lernpfad</a><div class="reading-layout"><article class="reading"><div class="eyebrow">WOCHE 1 · LEKTION ${String(lessons.indexOf(l)+1).padStart(2,'0')}</div><h1>${l.title}</h1><p class="lead">${l.intro}</p>${l.sections.map(([t,p])=>`<section class="reading-section"><h2>${t}</h2><p>${esc(p)}</p></section>`).join('')}<div class="example"><h3>${icon('spark')} ${l.example[0]}</h3><p>${esc(l.example[1])}</p></div><div class="callout"><strong>Genau hinschauen</strong>${esc(l.trap)}</div><section class="reading-section"><h2>Jetzt in deinen Worten</h2><p>${esc(l.reflection)}</p><label class="field" style="margin-top:16px"><span>Deine Erklärung (private Notiz, keine automatische Bewertung)</span><textarea id="lesson-note" maxlength="4000" placeholder="Wie würdest du es jemandem erklären?">${esc(state.notes[id]||'')}</textarea></label><button class="btn ghost" data-action="save-note" data-id="${id}">Notiz speichern</button><div class="note-status" id="note-status" role="status"></div></section><div class="reading-footer"><button class="btn" data-action="lesson-quiz" data-id="${id}">Wissen anwenden · ${Math.min(8,qs.length)} Aufgaben ${icon('arrow')}</button><a href="#practice/${id}" class="btn ghost">Alle ${qs.length} Aufgaben</a>${l.lab?`<a href="#lab/${l.lab}" class="btn secondary">Im Labor ausprobieren ${icon('flask')}</a>`:''}${lessons[lessons.indexOf(l)+1]?`<a href="#lesson/${lessons[lessons.indexOf(l)+1].id}" class="btn ghost">Nächste Lektion ${icon('chevron')}</a>`:''}</div></article><aside class="card sticky"><div class="eyebrow">DEINE LERNSCHLEIFE</div><h3>Verstehen wird Können.</h3><div class="separator"></div><p class="muted">01 · Erklärung lesen<br><br>02 · Beispiel nachvollziehen<br><br>03 · Selbst rechnen und begründen<br><br>04 · Ohne Vorlage überprüfen</p><div class="separator"></div><p class="help">${l.source}<br>Ca. ${l.minutes} Minuten für Erklärung und ersten Check. Rechenübungen kommen zusätzlich dazu.</p>${state.completed[id]?`<p class="completed-stamp" style="margin-top:18px">✓ Lektion abgeschlossen</p>`:''}</aside></div>`,'path');}
function reviewPage(){const due=dueQuestions(state),errors=Object.entries(state.errors).filter(([,e])=>!e.resolved);return shell(`${pageHead('WISSEN, DAS BLEIBT','Wiederholen mit Richtung.','Fehler zeigen dir, was als Nächstes hilfreich ist.')}<div class="grid two-cards"><section class="card"><div class="card-title"><h2>Heute fällig</h2>${icon('repeat')}</div><div class="score">${due.length}</div><p class="small muted">Wiederholungen nach 1, 3, 7 und 14 Tagen. Falsche oder mit Hinweis gelöste Aufgaben kommen sofort zurück.</p><button class="btn" data-action="review" style="margin-top:22px" ${due.length?'':'disabled'}>Fällige Aufgaben üben ${icon('arrow')}</button></section><section class="card"><div class="card-title"><h2>Eine kleine Tagesrunde</h2>${icon('spark')}</div><p class="small muted">Ein Mix aus passenden Grundlagen und deinen nächsten Lernschritten. Öffne bei neuen Begriffen zuerst die zugehörige Lektion.</p><button class="btn secondary" data-action="daily" style="margin-top:22px">5 Aufgaben starten ${icon('arrow')}</button><p class="help" style="margin-top:20px">Richtige Antworten nach eingeblendeten Hinweisen zählen als Übung, nicht als selbstständiger Nachweis.</p></section></div><div class="section-heading" style="margin-top:30px"><h2>Dein Fehlerprotokoll</h2><span class="pill gray">${errors.length} offen</span></div>${errors.length?errors.map(([id,e])=>{const q=questionById[id];return `<section class="card error-card"><div class="eyebrow">${topicById[q.lesson].title} · ${dateShort(e.date)}</div><h3>${esc(q.prompt)}</h3><details><summary>Richtige Regel und Erklärung ansehen</summary><div class="feedback info">${esc(q.explanation)}</div>${explainPanel(q)}</details><div class="grid two-cards"><label class="field">Was war deine Fehlerursache?<textarea maxlength="4000" id="error-note-${id}" placeholder="Zum Beispiel: ε übersehen …">${esc(e.note)}</textarea></label><label class="field">Meine Regel für das nächste Mal<textarea maxlength="4000" id="error-rule-${id}" placeholder="Worauf achtest du künftig?">${esc(e.rule)}</textarea></label></div><div class="inline-actions"><button class="btn ghost" data-action="save-error" data-id="${id}">Notiz speichern</button><button class="btn secondary" data-action="retry-question" data-id="${id}">Erneut versuchen ${icon('arrow')}</button><a href="${topicHref(q.lesson)}" class="small muted">Erklärung lesen</a></div></section>`;}).join(''):`<section class="card empty-state">${icon('check')}<h2>Raum für neue Erkenntnisse.</h2><p>Du hast gerade keine offenen Fehler. Sobald etwas noch nicht sitzt, findest du hier die Aufgabe, die Erklärung und Platz für deine eigene Regel.</p><a href="#path" class="btn secondary">Weiter zum Lernpfad</a></section>`}`,'review');}
function achievementPage(){const st=stats(state);return shell(`${pageHead('DEINE KLEINEN UND GROSSEN ERFOLGE','Das hast du dir erarbeitet.','Pokale für echtes Üben, Wiederholen und Anwenden.',`<span class="pill purple">${state.badges.length} / ${achievements.length} freigeschaltet</span>`)}<div class="card" style="margin-bottom:25px"><div class="card-title"><h2>${rankFor(st.xp)} · Level ${level(st.xp)} · ${st.xp} XP</h2>${icon('spark')}</div>${progressBar(percent(st.xp%150,150))}<p class="help">${150-st.xp%150} XP bis zum nächsten Level. 10 XP je erstmals ohne Hilfe gelöster Aufgabe, 25 je abgeschlossener Lektion, 50 je eigener Automatenkonstruktion, ${BOSS_XP} je erstem Bosssieg und ${QUEST_XP} je Tagesmission. Fällige Wiederholungen: 5 XP, höchstens einmal pro Aufgabe und Tag.</p></div><div class="grid achievement-grid">${achievements.map(a=>{const unlocked=state.badges.includes(a.id);return `<section class="card achievement ${unlocked?'unlocked':'locked'}"><span class="lock">${icon(unlocked?'check':'lock')}</span><div class="achievement-icon">${icon(a.icon)}</div><h3>${a.title}</h3><p>${a.description}</p>${unlocked?'<span class="pill" style="margin-top:17px">GESCHAFFT</span>':''}</section>`;}).join('')}</div>`,'achievements');}
function statsPage(){const st=stats(state);return shell(`${pageHead('DEIN LERNEN AUF EINEN BLICK','Fortschritt, der etwas bedeutet.','Deine eigenen Daten – ohne erfundene Ergebnisse oder Ranglisten.')}<div class="stats-grid">${[['target',st.attempts?st.accuracy+' %':'—','Richtige Antworten · alle Versuche'],['book',st.completed+'/19','Lektionen abgeschlossen'],['flame',st.streak,'Aktuelle Lernserie · Tage'],['clock',Math.floor(state.focusSeconds/60)+' Min.','Aktive Fokuszeit']].map(([i,v,t])=>`<div class="card stat-big">${icon(i)}<strong>${v}</strong><p>${t}</p></div>`).join('')}</div><div class="grid two-cards"><section class="card"><div class="card-title"><h2>Deine letzten 42 Tage</h2>${icon('calendar')}</div><p class="help">${st.attempts} Antworten insgesamt · ${st.unique} verschiedene Aufgaben ohne Hilfe gelöst.</p><div class="heatmap" role="img" aria-label="Lernaktivität der letzten 42 Tage">${Array.from({length:42},(_,i)=>{const d=addDays(today(),i-41),v=state.activity[d]?.attempts||0;return `<div class="heat" data-level="${v>=10?3:v>=5?2:v>0?1:0}" title="${dateFull(d)}: ${v} Antworten" aria-label="${dateFull(d)}: ${v} Antworten"></div>`;}).join('')}</div><div class="legend">Weniger ${[0,1,2,3].map(i=>`<span class="heat" data-level="${i}"></span>`).join('')} Mehr</div><a href="#achievements" class="btn ghost" style="margin-top:24px">Deine Erfolge ansehen ${icon('arrow')}</a></section><section class="card"><div class="card-title"><h2>Kompetenzen aufbauen</h2><span class="pill">${st.safe} sicher</span></div>${units.map(u=>{const completed=u.lessons.filter(id=>state.completed[id]).length,safe=u.lessons.filter(id=>mastery(state,id)==='safe').length;return `<div class="topic-bar"><div class="labels"><span>${u.title}</span><span>${completed}/${u.lessons.length}</span></div>${progressBar(percent(completed,u.lessons.length),true)}<p class="tiny muted">${safe} sicher · ${completed} abgeschlossen</p></div>`;}).join('')}<p class="help" style="margin-top:20px">Sicher = unterschiedliche Aufgaben an unterschiedlichen Tagen ohne Hilfe; offene Fehler setzen den Status zurück.</p></section></div><section class="card" style="margin-top:23px"><div class="card-title"><h2>Deine Wochenchecks</h2><a href="#check">Check starten →</a></div>${state.checks.length?`<div class="table-scroll"><table><thead><tr><th>Datum</th><th>Ergebnis</th><th>Bearbeitungszeit</th></tr></thead><tbody>${state.checks.slice(-10).reverse().map(c=>`<tr><td>${dateFull(c.date)}</td><td>${c.score}/10</td><td>${formatTime(c.seconds)}</td></tr>`).join('')}</tbody></table></div><p class="help">Wiederholungen derselben Checkfragen zeigen Routine. Für einen unabhängigen Leistungsnachweis brauchst du neue Aufgaben.</p>`:'<p class="small muted">Noch kein Wochencheck abgeschlossen. Beginne mit den Erklärungen und probiere anschließend den Check ohne Vorlage.</p>'}</section>`,'stats');}
function checkPage(){const best=Math.max(0,...state.checks.map(c=>c.score));return shell(`${pageHead('THEORETISCHE INFORMATIK · WOCHE 1 · DEIN PERSÖNLICHER NACHWEIS','Was bleibt ohne Vorlage?','Kein Zeitdruck. Zeig dir selbst, welche Grundlagen schon sitzen.')}<section class="card"><div class="check-summary"><div><strong>10</strong> Anwendungsfragen</div><div><strong>8/10</strong> Persönliches Trainingsziel</div><div><strong>2</strong> Eigene Automaten</div></div><p class="small muted">Die Aufgaben prüfen den Stoff deines Wochenchecks. Lösungen und Erklärungen erscheinen erst am Ende. Leg das Skript zur Seite und notiere deine Begründungen zusätzlich auf Papier. Die App bewertet die prüfbaren Antworten; deine Begründungen vergleichst du selbst mit den Erläuterungen.</p><button class="btn" data-action="weekly-check" style="margin-top:25px">Wochencheck starten ${icon('arrow')}</button>${state.checks.length?`<p class="help" style="margin-top:16px">Bisheriger Bestwert: ${best}/10. ${state.checks.length} Durchläufe.</p>`:''}</section><section class="card" style="margin-top:24px"><h2>Der praktische Teil</h2><p class="small muted" style="margin-top:12px">Erstelle die Übergänge und Endzustände ohne Vorlage. Beide Automaten werden vollständig auf Sprachgleichheit geprüft. Zustandsnamen sind für die Aufgabe vorgegeben.</p>${[['ends1','Binärwörter, die auf 1 enden'],['alternate','Binärwörter ohne gleiche Nachbarn']].map(([id,t])=>`<div class="lesson-row"><span class="lesson-num ${state.builders[id]?'current':''}">${icon(state.builders[id]?'check':'nodes')}</span><div><h3>${t}</h3><p>${state.builders[id]?'Ohne Vorlage konstruiert':'Noch offen · eigene Konstruktion'}</p></div><button class="btn secondary" style="margin-left:auto" data-action="open-builder" data-id="${id}">Bauen</button></div>`).join('')}<p class="help" style="margin-top:22px">Der Wochenpokal wird erst bei mindestens 8/10 und beiden erfolgreich gebauten Pflichtautomaten freigeschaltet. Das ist ein Trainingsziel, keine offizielle Notengrenze.</p></section>`,'path');}
function settingsPage(){return shell(`${pageHead('DEIN LERNRAUM, DEINE EINSTELLUNGEN','So passt Orbit zu dir.','Lernziel, Sicherung und die Grundlagen dieser App.')}<div class="settings-grid"><section class="card"><h2>Deine Ziele</h2><label class="field">Tagesziel<select id="goal">${[5,10,15].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} verschiedene richtige Aufgaben</option>`).join('')}</select></label>${subjects.map(sub=>`<label class="field">Prüfung ${sub.title}<input id="exam-date-${sub.id}" type="date" value="${sub.id==='ti'?state.examDate:state.examDates[sub.id]}" min="2020-01-01" max="2100-12-31"></label>`).join('')}<button class="btn" data-action="save-settings">Ziele speichern</button><p class="help" style="margin-top:15px">Der TI-Wochenplan bleibt an den Originaldaten 21.09.–20.11.2026 ausgerichtet. Geänderte Prüfungstermine passen die Countdowns an.</p></section><section class="card"><h2>Vom PC aufs Handy</h2><p>Der Lernstand wird nur in diesem Browser gespeichert. Es gibt kein Konto und keine automatische Synchronisierung. Exportiere ihn auf einem Gerät und importiere die Datei auf dem anderen.</p><button class="btn secondary" data-action="export">${icon('download')} Fortschritt exportieren</button><button class="btn ghost" data-action="import">Sicherung importieren</button><input type="file" class="file-input" id="import-file" accept="application/json,.json"><p class="help" style="margin-top:17px">Beim Import prüfst du erst die Zusammenfassung. Nach deiner Bestätigung ersetzt die Sicherung den aktuellen Stand. Beim Löschen von Browserdaten geht der lokale Stand verloren.</p><div id="import-preview" role="status"></div></section><section class="card"><h2>Deine App auf dem Startbildschirm</h2><p>iPhone: In Safari öffnen → Teilen → „Zum Home-Bildschirm“. Android: Im Browsermenü „App installieren“ oder „Zum Startbildschirm hinzufügen“.</p>${installPrompt?'<button class="btn" data-action="install">Orbit installieren</button>':''}<p class="help">Nach dem ersten vollständigen Laden funktioniert das Lernmaterial auch offline. Für die erste Nutzung und Updates benötigst du eine Verbindung. Fortschrittsexport bleibt weiterhin wichtig.</p><div class="separator"></div><a href="#stats" class="btn secondary">${icon('chart')} Statistik öffnen</a></section><section class="card"><h2>Woher kommen die Inhalte?</h2><p>Woche 1 wurde aus deinem 42-seitigen Lernskript neu als interaktives Training aufgebaut. Der Neun-Wochen-Pfad folgt deinem Masterplan.</p><ul class="source-list"><li>Lernskript Woche 1: Grundlagen, Beispiele und Korrekturen, S. 3–41.</li><li>Masterplan zur Klausur am 20.11.2026: Wochen, Ziele und Wiederholungen, S. 2–8.</li><li>Aufgaben 1–4 und die im Skript benannten Vorlesungsstellen.</li></ul><p class="help">Original-PDFs sind nicht Bestandteil der öffentlichen App. Bei Lektionen stehen genaue Fundstellen. Für die späteren Kapitel gibt es eigene Kurzüberblicke und Themenübungen in der Trainingsarena. Die ausführlichen Lektionen sind weiterhin auf Woche 1 konzentriert. Die sechs Probeklausuren verwenden eigene Aufgaben nach den Themen der Vorlesung und der Punkteverteilung der Altklausur. Prüfungsdauer und Hilfsmittel sind hier nicht als bestätigt hinterlegt.</p></section><section class="card"><h2>Speicher verwalten</h2><p>Ein Neustart löscht nur deinen lokalen Orbit-Lernstand. Exportiere vorher eine Sicherung, wenn du ihn behalten möchtest.</p>${storageBlocked?'<button class="btn secondary" data-action="recover">Nach Sicherung neu speichern</button>':''}<button class="btn danger" data-action="reset">Lernstand zurücksetzen</button></section><section class="card"><h2>Dein Wochenrhythmus</h2><p>Mo, Di, Do, Fr jeweils 75 Minuten; Sa zweimal 75 Minuten; So 30 Minuten. Mittwoch ist frei oder Puffer.</p><p class="help">Eine Standard-Einheit: 10 Minuten abrufen, 15 verstehen, 40 selbst rechnen, 10 korrigieren. Die kurzen App-Lektionen ergänzen deine handschriftlichen Aufgaben. App-Nutzung allein bestätigt noch keine Klausurreife.</p><a href="https://github.com/76patrik/quiet-orbit-lab" target="_blank" rel="noreferrer" class="small lime">Quellcode auf GitHub ↗</a></section></div>`,'settings');}
function questList(quests){return quests.map(q=>`<div class="quest ${q.done?'done':''}"><span class="quest-icon">${icon(q.done?'check':q.icon)}</span><div><h3>${q.title}</h3><p>${q.description}</p>${progressBar(percent(q.progress,q.target),!q.done)}</div><span class="quest-xp">${q.done?'Erfüllt':`+${QUEST_XP} XP`}</span></div>`).join('');}
function playPage(){
  const st=stats(state),day=today(),quests=questStatus(state,day),due=cardsDue(state,day),deck=cardDeck(state,day).length,best=bestBlitz(state),rankIndex=ranks.indexOf(rankFor(st.xp));
  return shell(`${pageHead('THEORETISCHE INFORMATIK · SPIELEN','Lernen mit Spielgefühl.','Missionen, Karteikarten, Blitzrunden und Bosskämpfe. Jede Runde trainiert das Abrufen ohne Vorlage.',`<a href="#achievements" class="pill purple">${icon('trophy')} ${state.badges.length} / ${achievements.length} Pokale</a>`)}<div class="grid play-grid"><section class="card rank-card"><div class="eyebrow">DEIN RANG</div><h2>${rankFor(st.xp)}</h2><p class="small muted">Level ${level(st.xp)} · ${st.xp} XP</p>${progressBar(percent(st.xp%LEVEL_XP,LEVEL_XP))}<small class="muted">${LEVEL_XP-st.xp%LEVEL_XP} XP bis Level ${level(st.xp)+1}${rankIndex<ranks.length-1?` · danach wartet ${ranks[rankIndex+1]}`:''}</small><div class="rank-track" aria-hidden="true">${ranks.map((r,i)=>`<span class="${i<=rankIndex?'reached':''}" title="${r}"></span>`).join('')}</div></section><section class="card"><div class="card-title"><h2>Tagesmissionen</h2><span class="pill gray">${quests.filter(q=>q.done).length} / 3</span></div>${questList(quests)}<p class="help" style="margin-top:12px">Jeden Tag drei neue Missionen. Um Mitternacht (Berlin) wechseln sie.</p></section></div><div class="grid mode-grid"><section class="card mode-card"><span class="mode-icon">${icon('layers')}</span><h2>Karteikarten</h2><p>Karte ansehen, selbst erklären, umdrehen und ehrlich einschätzen. Was sitzt, kommt seltener wieder.</p><div class="mode-meta"><span><strong>${due}</strong> fällig</span><span><strong>${deck}</strong> in der heutigen Runde</span><span><strong>${Object.keys(state.cards).length}</strong> / ${cards.length} entdeckt</span></div><button class="btn" data-action="start-cards" ${deck?'':'disabled'}>${deck?'Karten ziehen':'Heute alles erledigt'} ${icon('arrow')}</button></section><section class="card mode-card"><span class="mode-icon">${icon('spark')}</span><h2>Blitzrunde</h2><p>${BLITZ_SECONDS} Sekunden, so viele richtige Antworten wie möglich. Ideal für zwischendurch.</p><div class="mode-meta"><span>Rekord <strong>${best}</strong></span><span><strong>${state.blitz.length}</strong> Runden gespielt</span></div><button class="btn" data-action="start-blitz">Blitzrunde starten ${icon('arrow')}</button></section></div><section style="margin-top:26px"><div class="section-heading"><h2>Bosskämpfe · Woche 1</h2><span class="small muted">${Object.keys(state.bosses).length} / ${units.length} besiegt</span></div><div class="grid boss-grid">${units.map(u=>{const won=state.bosses[u.id],size=Math.min(BOSS_SIZE,bossPool(u.id).length),ready=u.lessons.every(id=>state.completed[id]);return `<section class="card boss-card ${won?'won':''}"><span class="boss-icon">${icon(won?'trophy':'shield')}</span><div class="eyebrow">${u.title}</div><h3>${u.boss}</h3><p class="small muted">${size} Aufgaben · ${BOSS_LIVES} Leben · keine Hinweise</p><p class="tiny ${won?'lime':'muted'}">${won?`Besiegt am ${dateShort(won)}`:ready?'Alle Lektionen abgeschlossen. Bereit!':`${u.lessons.filter(id=>state.completed[id]).length}/${u.lessons.length} Lektionen abgeschlossen`}</p><button class="btn ${won?'secondary':''}" data-action="start-boss" data-id="${u.id}">${won?'Revanche':'Herausfordern'} ${icon('arrow')}</button></section>`;}).join('')}</div></section><p class="help" style="margin-top:20px">Boss- und Übungsantworten zählen wie normale Aufgaben und planen Wiederholungen. Karteikarten und Blitzrunden sind Trainingsspiele: Sie geben Missionsfortschritt, zählen aber nicht als Kompetenznachweis. Ein erster Bosssieg bringt ${BOSS_XP} XP, jede Mission ${QUEST_XP} XP.</p>`,'play');
}
let cardSession=null;
function startCards(){
  const deck=cardDeck(state,today());if(!deck.length){toast('Heute sind keine Karteikarten mehr fällig.');return;}
  cardSession={items:deck.map(c=>c.id),index:0,flipped:false,known:0,again:0,requeued:{}};go('cards');
}
function cardsPage(){
  if(!cardSession)return shell(`<section class="card empty-state">${icon('layers')}<h2>Bereit für deine Karteikarten?</h2><p>${cardsDue(state,today())} Karten sind fällig. Neue Karten kommen in Kursreihenfolge dazu, höchstens 10 pro Tag.</p><button class="btn" data-action="start-cards">Karten ziehen</button></section>`,'play');
  const total=cardSession.items.length;
  if(cardSession.index>=total)return shell(`<div class="quiz"><section class="card quiz-result"><div class="result-symbol">${icon('layers')}</div><div class="eyebrow">KARTEIKARTEN · GESCHAFFT</div><h1>${cardSession.known>=cardSession.again?'Dein Stapel wird leichter.':'Gut, dass du ehrlich warst.'}</h1><div class="score">${cardSession.known}<span> / ${total}</span></div><p class="muted small">gewusst · ${cardSession.again}× „nochmal“</p><p class="small muted" style="margin-top:18px">Gewusste Karten kommen nach 1, 3, 7, 14 und 30 Tagen wieder. „Nochmal“-Karten bleiben heute fällig.</p><div class="result-actions">${planNextButton()}<a href="#play" class="btn secondary">Zurück zum Spielen</a><button class="btn secondary" data-action="start-cards">Weitere Karten</button></div></section></div>`,'play');
  const c=cardById[cardSession.items[cardSession.index]],l=topicById[c.lesson],box=state.cards[c.id]?.box??0;
  return shell(`<div class="quiz"><div class="quiz-top"><a href="#play" class="back-link" style="margin:0">${icon('back')} Stapel verlassen</a><span>${cardSession.index+1} / ${total}</span></div>${progressBar(percent(cardSession.index,total),true)}<section class="card flashcard ${cardSession.flipped?'flipped':''}" style="margin-top:22px"><div class="eyebrow">${esc(l.title)} · ${state.cards[c.id]?`Fach ${box+1}`:'Neue Karte'}</div><h1>${esc(c.front)}</h1>${cardSession.flipped?`<div class="flash-back"><p>${esc(c.back)}</p></div><p class="help">Wie gut konntest du das vorher selbst erklären?</p><div class="card-rating"><button class="btn danger" data-action="rate-card" data-id="again">Nochmal</button><button class="btn secondary" data-action="rate-card" data-id="hard">Schwer</button><button class="btn" data-action="rate-card" data-id="good">Gewusst ${icon('check')}</button></div>`:`<p class="help flash-prompt">Erkläre es erst in Gedanken oder laut. Dann umdrehen.</p><button class="btn full" data-action="flip-card">Umdrehen</button>`}<a class="small muted" style="display:inline-block;margin-top:18px" href="${topicHref(c.lesson)}">Erklärung öffnen</a></section></div>`,'play');
}
function rateCurrentCard(rating){
  const id=cardSession.items[cardSession.index];
  reward(()=>rateCard(state,id,rating));
  if(rating==='good')cardSession.known++;
  if(rating==='again'){cardSession.again++;if(!cardSession.requeued[id]){cardSession.requeued[id]=true;cardSession.items.push(id);}}
  cardSession.index++;cardSession.flipped=false;persist();render();
}
let blitz=null,blitzTimer=null;
function startBlitz(){
  blitz={items:shuffled(blitzPool(state)),index:0,score:0,answered:0,endsAt:Date.now()+BLITZ_SECONDS*1000,last:null,over:false,best:bestBlitz(state),options:{}};
  clearInterval(blitzTimer);blitzTimer=setInterval(tickBlitz,200);go('blitz');
}
function tickBlitz(){
  if(!blitz||blitz.over){clearInterval(blitzTimer);return;}
  const left=Math.max(0,blitz.endsAt-Date.now()),time=document.querySelector('#blitz-time'),bar=document.querySelector('#blitz-bar');
  if(time)time.textContent=Math.ceil(left/1000);if(bar)bar.style.width=`${left/(BLITZ_SECONDS*10)}%`;
  if(left<=0)endBlitz();
}
function endBlitz(){
  if(!blitz||blitz.over)return;blitz.over=true;clearInterval(blitzTimer);
  reward(()=>recordBlitz(state,blitz.score,blitz.answered));persist();if(route()[0]==='blitz')render();
}
function answerBlitz(value){
  if(!blitz||blitz.over||Date.now()>blitz.endsAt){endBlitz();return;}
  const q=blitz.items[blitz.index%blitz.items.length];let ok=false;
  try{ok=grade(q,value);}catch{ok=false;}
  blitz.answered++;if(ok)blitz.score++;blitz.last={ok,q};blitz.index++;render();
}
function blitzPage(){
  if(!blitz)return shell(`<section class="card empty-state">${icon('spark')}<h2>${BLITZ_SECONDS} Sekunden. Los geht's?</h2><p>Beantworte so viele Aufgaben wie möglich. Dein Rekord: ${bestBlitz(state)}.</p><button class="btn" data-action="start-blitz">Blitzrunde starten</button></section>`,'play');
  if(blitz.over){const record=blitz.score>blitz.best;return shell(`<div class="quiz"><section class="card quiz-result"><div class="result-symbol">${icon(record?'trophy':'spark')}</div><div class="eyebrow">BLITZRUNDE · ZEIT ABGELAUFEN</div><h1>${record?'Neuer Rekord!':blitz.score?'Stark reagiert.':'Aufwärmen gehört dazu.'}</h1><div class="score">${blitz.score}<span> richtig</span></div><p class="muted small">${blitz.answered} Antworten · bisheriger Rekord ${blitz.best}</p><p class="small muted" style="margin-top:18px">Blitzrunden trainieren schnelles Abrufen. Sie ändern keine Wiederholungstermine.</p><div class="result-actions"><button class="btn" data-action="start-blitz">Nochmal</button><a href="#play" class="btn secondary">Zurück zum Spielen</a></div></section></div>`,'play');}
  const q=blitz.items[blitz.index%blitz.items.length],left=Math.max(0,blitz.endsAt-Date.now());
  if(q.options&&!blitz.options[q.id+blitz.index])blitz.options[q.id+blitz.index]=shuffled(q.options.map((text,index)=>({text,index})));
  const last=blitz.last;
  return shell(`<div class="quiz"><div class="blitz-top"><a href="#play" class="back-link" style="margin:0">${icon('back')} Abbrechen</a><span class="blitz-time" aria-label="Sekunden übrig"><span id="blitz-time">${Math.ceil(left/1000)}</span>s</span><span class="blitz-score">${icon('spark')} ${blitz.score}</span></div><div class="progress"><span id="blitz-bar" style="width:${left/(BLITZ_SECONDS*10)}%"></span></div><section class="card quiz-card blitz-card" style="margin-top:18px"><div class="eyebrow">${esc(topicById[q.lesson].title)}</div><h1>${esc(q.prompt)}</h1>${q.type==='choice'?`<div class="answers">${blitz.options[q.id+blitz.index].map(({text,index},i)=>`<button class="answer" data-action="blitz-answer" data-index="${index}"><span class="answer-letter">${String.fromCharCode(65+i)}</span>${esc(text)}</button>`).join('')}</div>`:`<label class="field"><span>Deine Zahl</span><input id="blitz-input" inputmode="numeric" autocomplete="off" placeholder="Zahl eingeben, Enter"></label><button class="btn full" data-action="blitz-submit">Antworten ${icon('arrow')}</button>`}</section>${last?`<p class="blitz-last ${last.ok?'ok':'no'}" role="status">${last.ok?`${icon('check')} Richtig`:`${icon('close')} Richtig wäre: ${esc(answerLabel(last.q))}`}</p>`:''}</div>`,'play');
}
// Tagesplan: ein Schritt nach dem anderen, statt zwischen Bereichen wählen zu müssen.
const openStep=plan=>plan.steps.find(s=>!s.done&&!s.info);
function planCard(){
  const plan=todayPlan(state,today()),next=openStep(plan),notices=examNotices(state,today()),sch=plan.schedule;
  return `<section class="card plan-card"><div class="plan-head"><div><div class="eyebrow">HEUTE · ${plan.week?`WOCHE ${plan.week.n} VON ${weeks.length}`:'NACH DEM NEUN-WOCHEN-PLAN'}${plan.minutes?` · CA. ${plan.minutes} MIN.`:''}</div><h2>${next?'Dein Plan für heute':'Für heute ist alles erledigt.'}</h2></div>${plan.week?`<span class="pill ${sch.onTrack?'':'gray'}">${sch.onTrack?`${icon('check')} Im Plan`:`Noch ${sch.missing.length} ${sch.missing.length===1?'Thema':'Themen'} bis heute geplant`}</span>`:''}</div><ol class="plan-steps">${plan.steps.map((st,i)=>`<li class="plan-step ${st.done?'done':''} ${st===next?'current':''}"><span class="plan-num">${st.done?icon('check'):i+1}</span><div><h3>${st.info?st.title:`<button class="plan-link" data-action="plan-step" data-id="${st.id}">${esc(st.title)}</button>`}</h3><p>${esc(st.detail)}</p></div>${st.minutes&&!st.done?`<span class="plan-min">${st.minutes} Min.</span>`:''}</li>`).join('')}</ol>${next?`<button class="btn plan-go" data-action="plan-next">Weiter: ${esc(next.title)} ${icon('arrow')}</button>`:`<p class="small muted">Gut gemacht. Wenn du noch Lust hast: <a class="lime" href="#play">eine Blitzrunde spielen</a> oder <a class="lime" href="#practice">frei trainieren</a>.</p>`}${notices.map(n=>`<p class="plan-notice">${icon('flag')} ${esc(n.text)}${n.status==='pending'?' <a class="lime" href="#subjects">Mehr</a>':''}</p>`).join('')}</section>`;
}
function explainPanel(q){
  const e=explainFor(q);if(!e)return '';
  return `<div class="explain-panel"><div class="eyebrow">AUS DER LEKTION · ${esc(e.topic)}</div>${e.blocks.map(b=>`<h4>${esc(b.title)}</h4><p>${esc(b.text)}</p>`).join('')}${e.more.length?`<details><summary>Weitere Abschnitte dieser Lektion (${e.more.length})</summary>${e.more.map(b=>`<h4>${esc(b.title)}</h4><p>${esc(b.text)}</p>`).join('')}</details>`:''}<p class="help">${esc(e.source)} · <a class="lime" href="${topicHref(q.lesson)}">Ganze Seite öffnen</a></p></div>`;
}
function planNextButton(){const next=openStep(todayPlan(state,today()));return next?`<button class="btn" data-action="plan-next">Nächster Schritt: ${esc(next.title)} ${icon('arrow')}</button>`:`<a href="#" class="btn">Tagesplan erledigt ${icon('check')}</a>`;}
function runStep(step){
  if(!step)return;
  if(step.href){go(step.href.slice(1));return;}
  if(step.action==='review')startSession(dueQuestions(state).slice(0,15),{type:'review',title:'Deine fälligen Wiederholungen'});
  else if(step.action==='daily')dailySession();
  else if(step.action==='start-cards')startCards();
  else if(step.action==='start-boss'){const u=unitById[step.actionId];startSession(shuffled(bossPool(u.id)).slice(0,BOSS_SIZE),{type:'boss',unit:u.id,title:`Bosskampf · ${u.boss}`});}
}
function subjectsPage(){
  const schedule=examSchedule(state,today()),st=stats(state);
  return shell(`${pageHead('DEINE FÄCHER IM ORBIT','Drei Prüfungen, ein Prinzip.','Verstehen, anwenden, wiederholen – für jedes Fach. Inhalte entstehen aus deinen eigenen Unterlagen.')}<div class="stack">${schedule.map(e=>`<section class="card"><div class="card-title"><div><span class="pill ${e.status==='active'?'':'gray'}">${e.status==='active'?'INTERAKTIV VERFÜGBAR':'LERNMATERIALIEN FOLGEN'}</span><h2 style="margin-top:12px">${e.title}</h2></div>${icon(e.status==='active'?'book':'calendar')}</div><p><strong>Prüfung: ${dateFull(e.examDate)}</strong> · ${countdown(e.days)}</p><p class="small muted">${e.note}</p>${e.status==='active'?`${progressBar(percent(st.completed,lessons.length))}<small class="muted">${st.completed}/${lessons.length} Lektionen · ${st.due} Wiederholungen fällig</small><div class="inline-actions" style="margin-top:18px"><a href="#path" class="btn">Zum Lernpfad ${icon('arrow')}</a><a href="#review" class="btn ghost">Wiederholen</a></div>`:''}</section>`).join('')}</div><p class="help" style="margin-top:20px">Die Termine kannst du in den <a href="#settings" class="lime">Einstellungen</a> ändern. Lernstand, Wiederholungen und Pokale beziehen sich bisher nur auf Theoretische Informatik.</p>`,'subjects');
}
function notFound(){return shell('<section class="card empty-state"><h1>Hier ist noch kein Lernpfad.</h1><p>Diese Seite gibt es nicht.</p><a href="#path" class="btn">Zum Lernpfad</a></section>');}

// Die Einblend-Animation läuft nur beim Seitenwechsel, nicht bei jeder Antwort innerhalb einer Runde.
let lastHash=null,animateEnter=true;
function render(){
  animateEnter=location.hash!==lastHash;lastHash=location.hash;
  const [page='',id]=route();
  const pages={'':dashboard,subjects:subjectsPage,play:playPage,cards:cardsPage,blitz:blitzPage,path:pathPage,exams:examsPage,exam:examPage,practice:()=>practicePage(id),topic:()=>topicPage(id),lesson:()=>lessonPage(id),review:reviewPage,achievements:achievementPage,stats:statsPage,settings:settingsPage,check:checkPage,quiz:quizPage,lab:()=>labPage(id||'sets')};
  app.innerHTML=(pages[page]||notFound)();
  document.title=`${page==='lesson'&&lessonById[id]?lessonById[id].title:({subjects:'Fächer',play:'Spielen',cards:'Karteikarten',blitz:'Blitzrunde',practice:'Trainingsarena',topic:'Themenüberblick',exams:'Probeklausuren',path:'Lernpfad',review:'Wiederholen',stats:'Statistik',achievements:'Erfolge',settings:'Einstellungen',check:'Wochencheck',quiz:'Training',lab:'Übungslabor'}[page]||'Dein Lernraum')} · Orbit`;
  if(page==='lab'&&id==='dfa')renderDfaStage();
  if(page==='lab'&&id==='complexity')renderGrowth();
  if(page==='blitz')document.querySelector('#blitz-input')?.focus();
}

const shuffled=values=>{const out=[...values];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;};
function startSession(items,{type='practice',title='Eine Runde für dein Wissen',lesson=null,unit=null}={}){
  session={items:[...items],index:0,type,title,lesson,unit,lives:type==='boss'?BOSS_LIVES:null,combo:0,won:false,selected:null,input:'',confidence:null,hint:false,feedback:null,answers:[],finished:false,started:Date.now(),seconds:0,options:{}};
  for(const q of items)if(q.options)session.options[q.id]=shuffled(q.options.map((text,index)=>({text,index})));
  if(!items.length){toast('Gerade sind keine Aufgaben fällig.');return;}
  go('quiz');
}
function dailySession(){
  const eligible=new Set([...Object.keys(state.completed),state.lastLesson,nextLesson().id].filter(Boolean));
  const pool=questions.filter(q=>eligible.has(q.lesson));
  startSession(selectPractice(state,{count:5},pool),{title:'Deine Tagesrunde'});
}
function answerLabel(q){return q.type==='choice'?q.options[q.answer]:q.type==='set'?setLabel(q.answer):q.type==='number'?formatNumber(q.answer,q.unit):String(q.answer);}
function quizPage(){
  if(!session)return shell(`<section class="card empty-state">${icon('book')}<h2>Bereit für eine neue Runde?</h2><p>Ein laufender Durchgang bleibt nur bis zum Neuladen erhalten. Bereits gespeicherte Antworten findest du weiterhin in deiner Statistik.</p><button class="btn" data-action="daily">Tagesrunde starten</button></section>`,'review');
  if(session.finished)return resultPage();
  const q=session.items[session.index],f=session.feedback,isCheck=session.type==='check';
  return shell(`<div class="quiz"><div class="quiz-top"><a href="${session.lesson?'#lesson/'+session.lesson:session.type==='boss'?'#play':'#review'}" class="back-link" style="margin:0">${icon('back')} ${session.lesson?'Zur Lektion':session.type==='boss'?'Kampf verlassen':'Training verlassen'}</a><span class="quiz-status">${session.type==='boss'?`<span class="hearts" aria-label="${session.lives} von ${BOSS_LIVES} Leben">${Array.from({length:BOSS_LIVES},(_,i)=>`<span class="heart ${i<session.lives?'':'lost'}"></span>`).join('')}</span>`:''}${session.combo>=2?`<span class="combo">${icon('flame')} ${session.combo}er-Kette</span>`:''}<span>${session.index+1} / ${session.items.length}</span></span></div>${progressBar(percent(session.index,session.items.length),true)}<section class="card quiz-card" style="margin-top:22px"><div class="eyebrow">${esc(session.title)} · ${q.type==='choice'?'Eine Antwort wählen':q.type==='set'?'Eine Menge selbst berechnen':q.type==='regex'?'RegEx selbst konstruieren':'Selbst berechnen'}</div><h1 id="question-title">${esc(q.prompt)}</h1>${q.type==='choice'?`<div class="answers" role="group" aria-labelledby="question-title">${session.options[q.id].map(({text,index},i)=>`<button class="answer ${session.selected===index?'selected':''} ${f&&index===q.answer?'correct':''} ${f&&session.selected===index&&!f.correct?'wrong':''}" data-action="select-answer" data-index="${index}" aria-pressed="${session.selected===index}" ${f?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span>${esc(text)}</button>`).join('')}</div>`:`<label class="field"><span>Deine Antwort</span><input id="quiz-input" value="${esc(session.input)}" ${q.type==='number'&&q.answer>=0?`inputmode="${Number.isInteger(q.answer)&&!q.tolerance?'numeric':'decimal'}"`:''} autocomplete="off" spellcheck="false" maxlength="${q.type==='regex'?120:1000}" placeholder="${q.type==='set'?'Zum Beispiel: {ε, 0, 01} oder ∅':q.type==='regex'?'Zum Beispiel: (0|1)*':'Dein Ergebnis'}" ${f?'disabled':''}></label>${q.type==='set'||q.type==='regex'?symbolKeyboard('quiz-input',q.type==='regex'?['ε','∅','∪','(',')','*','+']:['ε','∅','{','}',',']):''}<p class="help">${q.type==='set'?'Reihenfolge und doppelte Einträge ändern eine Menge nicht. ε, eps oder epsilon stehen für das leere Wort.':q.type==='regex'?'Gleichwertige Ausdrücke sind erlaubt. Die App prüft die vollständige Sprache.':q.type==='number'&&(q.tolerance||!Number.isInteger(q.answer)||q.unit)?`Dezimalstellen mit Komma. Einheiten wie € oder % kannst du weglassen.${q.tolerance?` Rundungsabweichungen bis ±${formatNumber(q.tolerance)} werden akzeptiert.`:''}`:''}</p>`}${session.hint?`<div class="feedback info"><strong>Ein kleiner Hinweis</strong>${esc(q.hint)}<br><small>Diese Antwort zählt nicht als Nachweis ohne Hilfe.</small></div>`:''}${!f&&!isCheck?`<fieldset class="confidence"><legend>Wie sicher bist du? <span class="muted">(freiwillig)</span></legend>${[['guess','Geraten'],['unsure','Unsicher'],['sure','Sicher']].map(([v,label])=>`<button class="confidence-btn ${session.confidence===v?'selected':''}" data-action="confidence" data-value="${v}" aria-pressed="${session.confidence===v}">${label}</button>`).join('')}</fieldset>`:''}<div id="quiz-error" role="status"></div>${f?`<div class="feedback ${f.correct?'':'error'}" role="status"><strong>${f.correct?session.hint?'Richtig mit Unterstützung.':'Richtig. Das passt!':session.type==='boss'?`Treffer vom Boss. ${session.lives?`Noch ${session.lives} ${session.lives===1?'Leben':'Leben'}.`:'Keine Leben mehr.'}`:'Hier steckt dein nächster Lernschritt.'}${f.xp?` <span class="xp-pop">+${f.xp} XP</span>`:''}</strong>${esc(q.explanation)}${f.counter?`<p>${esc(f.counter)}</p>`:''}${!f.correct?`<p><strong>Eine richtige Antwort: ${esc(answerLabel(q))}</strong></p>`:''}</div>`:''}${f&&session.explain?explainPanel(q):''}<div class="quiz-controls">${f?`<button class="btn ghost" data-action="explain" aria-expanded="${!!session.explain}">${session.explain?'Erklärung ausblenden':'Warum? Genauer erklären'}</button><button class="btn" data-action="next-question">${session.type==='boss'&&!session.lives?'Kampf beenden':session.index+1===session.items.length?'Runde abschließen':'Nächste Aufgabe'} ${icon('arrow')}</button>`:`<div class="inline-actions">${!isCheck&&session.type!=='boss'?`<button class="btn ghost" data-action="hint" ${session.hint?'disabled':''}>Hinweis</button>`:''}<button class="btn ghost" data-action="skip">Weiß ich noch nicht</button></div><button class="btn" data-action="submit-answer">${isCheck?'Antwort festhalten':'Antwort prüfen'} ${icon('arrow')}</button>`}</div>${isCheck?'<p class="help" style="margin-top:20px">Im Wochencheck werden Lösungen und Bewertung erst am Ende angezeigt.</p>':''}</section></div>`,session.type==='boss'?'play':'review');
}
function submitAnswer(skip=false){
  if(!session||session.finished||session.feedback)return;
  const q=session.items[session.index];let value=q.type==='choice'?session.selected:document.querySelector('#quiz-input')?.value;
  if(q.type!=='choice')session.input=value||'';
  if(!skip&&(value===null||value===undefined||String(value).trim()==='')){document.querySelector('#quiz-error').innerHTML='<div class="feedback error">Wähle oder gib zuerst eine Antwort ein.</div>';return;}
  let correct=false,counter='';
  try{if(!skip){correct=grade(q,value);if(q.type==='regex'&&!correct){const test=compareRegex(value,q.answer);counter=`Gegenbeispiel: ${wordLabel(test.word)} wird von deinem Ausdruck ${test.actual?'angenommen':'abgelehnt'}, müsste aber ${test.expected?'angenommen':'abgelehnt'} werden.`;}}}
  catch(e){document.querySelector('#quiz-error').innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;return;}
  const answer={qid:q.id,correct,confidence:session.confidence,assisted:session.hint,value:skip?'':value,counter};
  session.answers.push(answer);
  if(session.type==='check'){nextQuestion();return;}
  const xp=reward(()=>{const badges=recordAnswer(state,q.id,correct,{assisted:session.hint,review:session.type==='review',confidence:session.confidence});if(correct&&!session.hint){session.combo++;badges.push(...recordCombo(state,session.combo));}else session.combo=0;return badges;});
  if(session.type==='boss'&&!correct)session.lives--;
  persist();session.feedback={correct,counter,xp};render();
}
function nextQuestion(){
  if(session.index+1>=session.items.length||(session.type==='boss'&&session.lives<=0)){finishSession();return;}
  session.index++;session.selected=null;session.input='';session.confidence=null;session.explain=false;session.hint=false;session.feedback=null;render();window.scrollTo({top:0,behavior:'instant'});
}
function finishSession(){
  if(session.finished)return;session.finished=true;session.seconds=Math.min(86400,Math.round((Date.now()-session.started)/1000));
  const earned=session.answers.filter(a=>a.correct&&!a.assisted).length;
  reward(()=>{
    const newBadges=[];
    if(session.type==='check'){
      for(const a of session.answers)newBadges.push(...recordAnswer(state,a.qid,a.correct,{confidence:a.confidence}));
      state.checks.push({date:today(),score:earned,seconds:session.seconds});newBadges.push(...updateBadges(state));
    }
    if(session.type==='boss'){session.firstWin=session.lives>0&&!state.bosses[session.unit];session.won=session.lives>0;newBadges.push(...recordBoss(state,session.unit,session.won));}
    if(session.lesson&&earned/session.items.length>=.8)newBadges.push(...completeLesson(state,session.lesson));
    return newBadges;
  });persist();render();window.scrollTo({top:0,behavior:'instant'});
}
function resultPage(){
  const earned=session.answers.filter(a=>a.correct&&!a.assisted).length,passed=session.type==='boss'?session.won:earned/session.items.length>=.8,boss=session.unit&&unitById[session.unit];
  const wrong=session.answers.filter(a=>!a.correct||a.assisted);
  return shell(`<div class="quiz"><section class="card quiz-result"><div class="result-symbol">${icon(passed?'trophy':'spark')}</div><div class="eyebrow">${esc(session.title)} · ${boss?passed?'SIEG':'NIEDERLAGE':'GESCHAFFT'}</div><h1>${boss?passed?`${boss.boss} ist besiegt!`:`${boss.boss} war heute stärker.`:passed?'Ein guter Schritt nach vorn.':'Du weißt jetzt, wo es weitergeht.'}</h1><div class="score">${earned}<span> / ${session.items.length}</span></div><p class="muted small">Ohne Hilfe richtig · ${formatTime(session.seconds)} Bearbeitungszeit</p><p class="small muted" style="margin-top:18px">${boss?passed?`Gewonnen mit ${session.lives} von ${BOSS_LIVES} Leben.${session.firstWin?` Erster Sieg: +${BOSS_XP} XP.`:''} Deine Antworten zählen auch für Wiederholungen.`:'Alle Leben verbraucht. Die falschen Aufgaben stehen jetzt in deinen Wiederholungen. Lies die passenden Lektionen und fordere den Boss erneut heraus.':session.lesson?passed?'Die Lektion ist abgeschlossen. Wiederhole sie später mit einer anderen Aufgabe, um sie sicher zu festigen.':'Die Lektion bleibt offen. Schau dir die Fehler an und probiere den Lektionscheck erneut.':session.type==='check'?passed?'Das Fragenziel ist erreicht. Für den Wochenpokal gehören noch die beiden eigenen Automaten dazu.':'Dein Ziel sind mindestens 8 von 10 Fragen. Nimm dir zuerst die unten aufgeführten Themen vor.':'Dein Fortschritt und deine Wiederholungstermine sind gespeichert.'}</p><div class="result-actions">${session.type!=='check'?planNextButton():''}${boss?`<button class="btn" data-action="start-boss" data-id="${session.unit}">${passed?'Revanche':'Erneut herausfordern'}</button><a href="#play" class="btn secondary">Zurück zum Spielen</a>`:session.lesson?`<button class="btn" data-action="lesson-quiz" data-id="${session.lesson}">${passed?'Lektion erneut üben':'Lektionscheck wiederholen'}</button><a href="#path" class="btn secondary">Zum Lernpfad</a>`:session.type==='check'?'<a href="#check" class="btn">Zum praktischen Teil</a><a href="#review" class="btn secondary">Fehler nacharbeiten</a>':'<a href="#practice" class="btn">Nächste Trainingsrunde</a><a href="#stats" class="btn secondary">Statistik ansehen</a>'}</div></section>${session.answers.map(a=>{const q=questionById[a.qid];return `<section class="card error-card"><div class="eyebrow">${a.correct?'RICHTIG':'NOCH ÜBEN'}${a.assisted?' · MIT HINWEIS':''} · ${topicById[q.lesson].title}</div><h3>${esc(q.prompt)}</h3><p class="help" style="margin-top:12px">Deine Antwort: ${esc(a.value===''?'Keine Antwort':q.type==='choice'?q.options[a.value]:a.value)}</p><div class="feedback ${a.correct?'':'error'}"><strong>${esc(answerLabel(q))}</strong>${esc(q.explanation)}${a.counter?`<p>${esc(a.counter)}</p>`:''}</div><details class="explain-details"><summary>Warum? Genauer erklären</summary>${explainPanel(q)}</details></section>`;}).join('')}</div>`,session.type==='boss'?'play':'review');
}
function symbolKeyboard(target,symbols){return `<div class="symbol-keyboard" aria-label="Mathematische Zeichen einfügen">${symbols.map(s=>`<button type="button" data-action="symbol" data-target="${target}" data-symbol="${esc(s)}" aria-label="${esc(s)} einfügen">${esc(s)}</button>`).join('')}</div>`;}

const labs=[['sets','layers','Sprachen'],['regex','code','RegEx'],['dfa','nodes','DEA-Lauf'],['builder','flask','DEA bauen'],['complexity','chart','Wachstum']];
function labPage(id){if(!labs.some(l=>l[0]===id))return notFound();return shell(`${pageHead('THEORETISCHE INFORMATIK · DEIN ÜBUNGSLABOR','Hier wird Theorie greifbar.','Verändere etwas. Beobachte das Ergebnis. Verstehe den Zusammenhang.')}<nav class="lab-tabs" aria-label="Lernlabore">${labs.map(([key,i,t])=>`<a href="#lab/${key}" class="${key===id?'active':''}" ${key===id?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}</nav>${{sets:setLab,regex:regexLab,dfa:dfaLab,builder:builderLab,complexity:complexityLab}[id]()}`,'lab');}
function setLab(){return `<div class="lab-grid"><section class="card"><h2>Mit Sprachen rechnen</h2><p class="help" style="margin-bottom:20px">Gib endliche Sprachen ein. Rechne erst selbst, dann lass dir die Entstehung zeigen.</p><label class="field">Sprache A<input id="set-a" value="{ε, 0}" maxlength="1000" autocomplete="off" spellcheck="false"></label><label class="field">Sprache B<input id="set-b" value="{1, 01}" maxlength="1000" autocomplete="off" spellcheck="false"></label><label class="field">Operation<select id="set-op"><option value="concat">A · B · Konkatenation</option><option value="union">A ∪ B · Vereinigung</option><option value="intersection">A ∩ B · Schnitt</option><option value="difference">A ∖ B · Differenz</option><option value="quotient">A / B · Rechtsquotient</option></select></label><label class="field">Dein vermutetes Ergebnis<input id="set-answer" placeholder="Zum Beispiel: {ε, 0, 01}" maxlength="1000" autocomplete="off" spellcheck="false"></label>${symbolKeyboard('set-answer',['ε','∅','{','}',','])}<div class="inline-actions"><button class="btn" data-action="set-check">Ergebnis prüfen</button><button class="btn ghost" data-action="set-solve">Herleitung zeigen</button></div></section><section class="card"><h2>Jedes Wort hat einen Weg.</h2><div id="set-output" role="status"><p class="muted small">Bei der Konkatenation entsteht aus jedem Paar ein Wort. Manche Paare liefern dasselbe Ergebnis – in der Ergebnismenge zählt es nur einmal.</p><div class="example"><h3>Ein Denkimpuls</h3><p>Wenn du ε mit 01 verkettest und 0 mit 1, was fällt dir auf?</p></div></div><div class="separator"></div><p class="help">A / B entfernt passende vollständige Endstücke aus B. Ein Komplement relativ zu Σ* kann unendlich sein und wird deshalb nicht als endliche Liste berechnet.</p><a href="#lesson/quotient" class="back-link" style="margin-top:14px">Rechtsquotient verstehen ${icon('arrow')}</a></section></div>`;}
function runSetLab(check){
  const output=document.querySelector('#set-output');
  try{
    const a=parseSet(document.querySelector('#set-a').value),b=parseSet(document.querySelector('#set-b').value),op=document.querySelector('#set-op').value,result=languageOperation(a,b,op);
    let feedback='';if(check){const guessed=parseSet(document.querySelector('#set-answer').value),ok=equalSets(guessed,result);feedback=`<div class="feedback ${ok?'':'error'}"><strong>${ok?'Genau richtig.':'Vergleiche deine Menge mit der Herleitung.'}</strong>${ok?'Du hast alle Ergebniswörter gefunden.':'Prüfe Reihenfolge, doppelte Ergebnisse und das leere Wort.'}</div>`;}
    let pairs=[];
    if(op==='concat')pairs=a.flatMap(x=>b.map(y=>`${wordLabel(x)} · ${wordLabel(y)} = ${wordLabel(x+y)}`));
    else if(op==='quotient')pairs=a.flatMap(x=>b.filter(y=>x.endsWith(y)).map(y=>`${wordLabel(x)} ohne Suffix ${wordLabel(y)} → ${wordLabel(y?x.slice(0,-y.length):x)}`));
    else pairs=result.map(w=>`${wordLabel(w)}: ${a.includes(w)?'in A':'nicht in A'}, ${b.includes(w)?'in B':'nicht in B'}`);
    output.innerHTML=`${feedback}<div class="eyebrow" style="margin-top:20px">DEIN ERGEBNIS</div><div class="set-result">${esc(setLabel(result.slice(0,80)))}</div><p class="help">${result.length} verschiedene Wörter.${result.length>80?' Angezeigt werden die ersten 80.':''}${op==='concat'?` ${a.length*b.length} Paare wurden gebildet.`:''}</p><div class="separator"></div><h3>So entsteht die Menge</h3><div class="pair-list">${pairs.length?pairs.slice(0,40).map(p=>esc(p)).join('<br>'):'Kein passendes Paar bzw. Wort. Deshalb ist das Ergebnis ∅.'}${pairs.length>40?'<br>… weitere Schritte nicht angezeigt.':''}</div><p class="help" style="margin-top:18px">Freies Experimentieren vergibt keine XP. Die Lektionsaufgaben liefern deinen Lernnachweis.</p>`;
  }catch(e){output.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}
}
const regexTasks=[{id:'end01',title:'Endet auf 01',answer:'(0|1)*01'},{id:'two',title:'Genau zwei Einsen',answer:'0*10*10*'},{id:'none',title:'Keine Eins',answer:'0*'},{id:'len3',title:'Genau Länge 3',answer:'(0|1)(0|1)(0|1)'},{id:'even',title:'Gerade Anzahl Einsen',answer:'0*(10*10*)*'},{id:'penult0',title:'Vorletztes Zeichen 0',answer:'(0|1)*0(0|1)'}];
function regexLab(){return `<div class="lab-grid"><section class="card"><h2>Dein Muster, deine Sprache</h2><p class="help" style="margin-bottom:20px">Alphabet: {0,1}. Erlaubt sind ε, ∅, Vereinigung (∪ oder |), Verkettung, *, + und Klammern.</p><label class="field">Konstruktionsaufgabe<select id="regex-task">${regexTasks.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></label><label class="field">Dein regulärer Ausdruck<input id="regex-expression" value="(0|1)*1" maxlength="120" spellcheck="false" autocomplete="off"></label>${symbolKeyboard('regex-expression',['0','1','ε','∅','∪','(',')','*','+'])}<label class="field">Zusätzlich ein Wort testen (leer lassen für ε)<input id="regex-word" value="101" maxlength="50" spellcheck="false" autocomplete="off" inputmode="numeric"></label><div class="inline-actions"><button class="btn" data-action="regex-check">Aufgabe prüfen</button><button class="btn secondary" data-action="regex-preview">Wörter ausprobieren</button></div><p class="help" style="margin-top:20px">Jede Aufgabe akzeptiert auch anders geschriebene, gleichwertige Ausdrücke. Ein vollständiger Vergleich liefert bei Abweichung ein kürzestes Gegenbeispiel.</p></section><section class="card"><h2>Was akzeptiert dein Ausdruck?</h2><div id="regex-output" role="status"><p class="small muted">Starte mit dem Beispielausdruck und teste ihn. Passt er bereits zur Aufgabe „endet auf 01“?</p><div class="example"><h3>Genau hinsehen</h3><p>Ein RegEx beschreibt hier immer das ganze Wort. Eine passende Teilzeichenfolge allein reicht nicht.</p></div></div></section></div>`;}
function runRegexLab(check){
  const output=document.querySelector('#regex-output');
  try{
    const expr=document.querySelector('#regex-expression').value,matcher=compileRegex(expr),word=document.querySelector('#regex-word').value.trim();
    if(/[^01]/.test(word))throw new Error('Das Testwort darf nur 0 und 1 enthalten. Für ε lass das Feld leer.');
    const task=regexTasks.find(t=>t.id===document.querySelector('#regex-task').value);let result='';
    if(check){const comp=compareRegex(expr,task.answer);result=`<div class="feedback ${comp.equal?'':'error'}"><strong>${comp.equal?'Die Sprache stimmt vollständig überein.':'Ein Gegenbeispiel zeigt den Unterschied.'}</strong>${comp.equal?`Dein Ausdruck erfüllt „${task.title}“. Der vollständige Vergleich ist erfolgreich.`:`${wordLabel(comp.word)} wird von deinem Ausdruck ${comp.actual?'akzeptiert':'abgelehnt'}, müsste für „${task.title}“ aber ${comp.expected?'akzeptiert':'abgelehnt'} werden.`}</div>`;}
    const accepted=matcher.test(word);output.innerHTML=`${result}<p style="margin:20px 0"><span class="chip ${accepted?'accept':'reject'}">${esc(wordLabel(word))}</span> <span class="small">${accepted?'wird akzeptiert':'wird abgelehnt'}</span></p><h3>Alle Binärwörter bis Länge 3</h3><div class="chips" style="margin-top:15px">${binaryWords(3).map(w=>`<span class="chip ${matcher.test(w)?'accept':'reject'}" title="${matcher.test(w)?'Akzeptiert':'Abgelehnt'}">${wordLabel(w)}</span>`).join('')}</div><p class="help" style="margin-top:20px">Grün: akzeptiert. Rot: abgelehnt. Diese Vorschau ist endlich und allein kein Beweis. „Aufgabe prüfen“ vergleicht die vollständigen Sprachen.</p>`;
  }catch(e){output.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}
}
function currentDfa(){const m=machines[dfaKey];return {...m,accept:dfaComplement?m.states.filter(s=>!m.accept.includes(s)):m.accept};}
function dfaLab(){return `<section class="card"><div class="lab-grid"><div><h2>Schritt für Schritt durch den Automaten</h2><label class="field" style="margin-top:20px">Beispielautomat<select id="dfa-machine">${Object.entries(machines).map(([key,m])=>`<option value="${key}" ${key===dfaKey?'selected':''}>${m.name}</option>`).join('')}</select></label><label class="field">Eingabewort (leer für ε)<input id="dfa-word" value="${esc(dfaWord)}" maxlength="40" spellcheck="false" inputmode="numeric"></label><label class="check-line"><input type="checkbox" id="dfa-complement" ${dfaComplement?'checked':''}> Komplement bilden: Endzustände umkehren</label><div class="inline-actions"><button class="btn" data-action="dfa-start">Wort laden</button><button class="btn secondary" data-action="dfa-step">Ein Schritt ${icon('arrow')}</button><button class="btn ghost" data-action="dfa-all">Bis zum Ende</button></div></div><div><div class="eyebrow">SO LIEST DU DIE ANZEIGE</div><p class="small muted">Die helle Markierung ist der aktuelle Zustand, ein Doppelkreis kennzeichnet akzeptierende Zustände. Die vollständige Übergangstabelle zeigt, wohin jedes Zeichen führt.</p><div class="callout" style="margin-top:20px"><strong>Erst am Ende entscheiden</strong>Akzeptanz wird nach dem vollständigen Wort geprüft. Bei ε bleibt der Automat im Startzustand.</div></div></div><div id="dfa-stage" aria-live="polite"></div></section>`;}
function renderDfaStage(){
  const target=document.querySelector('#dfa-stage');if(!target)return;
  try{
    const m=currentDfa(),run=runDfa(m,dfaWord),pos=Math.min(dfaPosition,dfaWord.length),cur=run.trace[pos],done=pos===dfaWord.length;
    target.innerHTML=`<div class="dfa-states" role="img" aria-label="Aktueller Zustand ${cur}. Akzeptierende Zustände ${m.accept.join(', ')}">${m.states.map(s=>`<div class="dfa-state ${s===cur?'active':''} ${m.accept.includes(s)?'accepting':''}">${s}<span class="state-name">${s===m.start?'Start':''}</span></div>`).join('')}</div><div class="word-tape" aria-label="Eingabewort, ${pos} von ${dfaWord.length} Zeichen gelesen">${dfaWord?[...dfaWord].map((c,i)=>`<span class="${i<pos?'read':i===pos?'next':''}">${c}</span>`).join(''):'<span>ε</span>'}</div><p class="small">${done?`Eingabe vollständig · ${m.accept.includes(cur)?'<strong class="lime">Akzeptiert</strong>':'<strong style="color:var(--red)">Abgelehnt</strong>'}`:`Schritt ${pos} von ${dfaWord.length} · nächstes Zeichen: <strong>${dfaWord[pos]}</strong>`}</p><div class="trace">${run.trace.slice(0,pos+1).map(esc).join(' → ')}</div><div class="table-scroll"><table><caption class="help" style="text-align:left">Vollständige Übergangsfunktion · Start: ${m.start} · F = ${esc(setLabel(m.accept))}</caption><thead><tr><th>Zustand</th><th>Bei 0</th><th>Bei 1</th><th>Bedeutung im Original</th></tr></thead><tbody>${m.states.map(s=>`<tr class="${s===cur?'current-row':''}"><td>${s===m.start?'→ ':''}${m.accept.includes(s)?'* ':''}${s}</td><td>${m.transitions[s][0]}</td><td>${m.transitions[s][1]}</td><td>${m.meanings[s]}</td></tr>`).join('')}</tbody></table></div>`;
  }catch(e){target.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}
}
function emptyBuilder(){const m=machines[builderKey];builderDraft={accept:[],transitions:Object.fromEntries(m.states.map(s=>[s,{'0':'','1':''}]))};}
function builderLab(){
  const m=machines[builderKey];if(!builderDraft.transitions?.[m.start]||Object.keys(builderDraft.transitions).length!==m.states.length)emptyBuilder();
  return `<section class="card"><div class="lab-grid"><div><h2>Dein Automat. Deine Übergänge.</h2><label class="field" style="margin-top:20px">Konstruktionsaufgabe<select id="builder-task">${['ends1','alternate','contains1','parity'].map(key=>`<option value="${key}" ${key===builderKey?'selected':''}>${machines[key].name}${['ends1','alternate'].includes(key)?' · Wochenziel':''}</option>`).join('')}</select></label><div class="builder-task"><strong>${m.description}</strong><p>Alphabet {0,1} · Startzustand ${m.start} · ${m.states.length} vorgegebene Zustände. Fülle jeden Übergang aus und wähle alle akzeptierenden Zustände.</p></div><p class="help">Andere korrekte Zustandszuordnungen werden anerkannt. Die Prüfung vergleicht die vollständige Sprache. Ein Gegenbeispiel zeigt dir bei Fehlern, welches Wort anders behandelt wird.</p></div><div><div class="eyebrow">SO BAUST DU EINEN DEA</div><p class="small muted">01 · Welche Information musst du merken?<br>02 · Was bedeutet jeder Zustand?<br>03 · Wie verändert 0 oder 1 diese Information?<br>04 · Welche Zustände erfüllen die Bedingung?</p><button class="btn ghost" data-action="builder-help" style="margin-top:20px" ${builderHelp?'disabled':''}>Zustandsideen als Hinweis</button>${builderHelp?`<div class="feedback info"><strong>Mit Unterstützung üben</strong>${m.states.map(s=>`${s}: ${m.meanings[s]}`).join('<br>')}<p>Dieser Versuch zählt nicht für den Pokal „ohne Vorlage“.</p></div>`:''}</div></div><div class="table-scroll"><table><thead><tr><th>Zustand</th><th>Bei 0 nach …</th><th>Bei 1 nach …</th><th>Akzeptiert?</th></tr></thead><tbody>${m.states.map(s=>`<tr><td>${s===m.start?'→ ':''}${s}</td>${['0','1'].map(c=>`<td><select aria-label="Übergang ${s} bei ${c}" data-builder-state="${s}" data-builder-char="${c}"><option value="">Wählen</option>${m.states.map(t=>`<option value="${t}" ${builderDraft.transitions[s][c]===t?'selected':''}>${t}</option>`).join('')}</select></td>`).join('')}<td><label class="check-line" style="margin:0"><input type="checkbox" data-builder-accept="${s}" ${builderDraft.accept.includes(s)?'checked':''} aria-label="${s} akzeptierend"><span>Ja</span></label></td></tr>`).join('')}</tbody></table></div><div class="inline-actions" style="margin-top:24px"><button class="btn" data-action="builder-check">Automat prüfen ${icon('check')}</button><button class="btn ghost" data-action="builder-reset">Ohne Vorlage neu beginnen</button></div><div id="builder-output" role="status"></div>${state.builders[builderKey]?'<p class="completed-stamp" style="margin-top:20px">✓ Diese Konstruktion wurde bereits ohne Vorlage gelöst.</p>':''}</section>`;
}
function checkBuilder(){const out=document.querySelector('#builder-output');try{const m=machines[builderKey],candidate={...m,accept:builderDraft.accept,transitions:builderDraft.transitions};const result=compareDfa(candidate,m);if(result.equal){if(!builderHelp){reward(()=>completeBuilder(state,builderKey));persist();}out.innerHTML=`<div class="feedback"><strong>Dein Automat erkennt genau die verlangte Sprache.</strong>Alle erreichbaren Zustandskombinationen wurden verglichen. ${builderHelp?'Gut mit Unterstützung geübt. Beginne später ohne Vorlage neu, um den Nachweis zu erbringen.':'Dein selbstständiger Konstruktionsnachweis ist gespeichert.'}</div>`;}else{const actual=runDfa(candidate,result.word);out.innerHTML=`<div class="feedback error"><strong>Gegenbeispiel: ${esc(wordLabel(result.word))}</strong>Dein Automat ${result.actual?'akzeptiert':'verwirft'} dieses Wort. Die Aufgabe verlangt, es ${result.expected?'anzunehmen':'abzulehnen'}.<p>Dein Lauf: ${actual.trace.join(' → ')}.</p><p>Prüfe die Zustandsbedeutung und die Übergänge auf diesem Weg.</p></div>`;}}catch(e){out.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}}
function complexityLab(){return `<div class="lab-grid"><section class="card"><h2>Ein kleines n macht einen großen Unterschied.</h2><p class="small muted" style="margin-top:15px">Bewege den Regler und vergleiche beispielhafte exakte Schrittzahlen. Die Balken sind logarithmisch skaliert, damit auch große Unterschiede sichtbar bleiben.</p><label class="field" style="margin-top:27px">Eingabegröße n: <strong id="growth-n" class="lime">10</strong><input type="range" id="growth-slider" min="1" max="30" value="10" aria-label="Eingabegröße n"></label><div id="growth-chart" role="status"></div><p class="help" style="margin-top:24px">Die Werte n, n², n³ und 2ⁿ sind hier konkrete Modellfunktionen. O(n²) selbst bezeichnet eine Klasse oberer Schranken, keine genaue Schrittzahl.</p></section><section class="card"><h2>Was passiert beim Verzehnfachen?</h2><div class="table-scroll"><table><thead><tr><th>Wachstum</th><th>Faktor bei n → 10n</th></tr></thead><tbody><tr><td>n</td><td>10</td></tr><tr><td>n²</td><td>100</td></tr><tr><td>n³</td><td>1.000</td></tr><tr><td>2ⁿ</td><td>2⁹ⁿ, abhängig von n</td></tr></tbody></table></div><div class="callout" style="margin-top:24px"><strong>Die wichtige Trennung</strong>Die Chomsky-Hierarchie ordnet Sprachklassen und Modelle. Eine O-Laufzeit lässt sich daraus nicht pauschal pro Zeile ablesen.</div><a href="#lesson/complexity" class="back-link" style="margin-top:20px">Die Grundlagen lesen ${icon('arrow')}</a></section></div>`;}
function renderGrowth(){const n=Number(document.querySelector('#growth-slider')?.value||10);const vals=[['n',n],['n²',n*n],['n³',n*n*n],['2ⁿ',2**n]];document.querySelector('#growth-n').textContent=n;document.querySelector('#growth-chart').innerHTML=vals.map(([name,value])=>`<div class="chart-row"><strong>${name}</strong><div class="chart-bar"><span style="width:${Math.max(1,Math.log2(value+1)/30*100)}%"></span></div><span class="number">${value.toLocaleString('de-DE')}</span></div>`).join('');}

let pendingImport=null;
function exportProgress(){
  const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`orbit-fortschritt-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Deine Sicherungsdatei wurde zum Download vorbereitet.');
}
function updateFocusDisplay(){
  const t=document.querySelector('#focus-timer'),b=document.querySelector('#focus-toggle');if(t)t.textContent=formatTime(focus.remaining);if(b)b.innerHTML=icon(focus.running?'pause':'play')+(focus.running?'Pausieren':'Fokus starten');
}
app.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();
  const action=button.dataset.action,id=button.dataset.id;
  try{
    switch(action){
      case 'week':selectedWeek=Number(button.dataset.week);render();break;
      case 'daily':dailySession();break;
      case 'explain':if(session){session.explain=!session.explain;render();}break;
      case 'plan-next':runStep(openStep(todayPlan(state,today())));break;
      case 'plan-step':runStep(todayPlan(state,today()).steps.find(s=>s.id===id));break;
      case 'start-cards':startCards();break;
      case 'flip-card':if(cardSession){cardSession.flipped=true;render();}break;
      case 'rate-card':if(cardSession&&cardSession.flipped)rateCurrentCard(id);break;
      case 'start-blitz':startBlitz();break;
      case 'blitz-answer':answerBlitz(button.dataset.index);break;
      case 'blitz-submit':{const v=document.querySelector('#blitz-input')?.value.trim();if(v)answerBlitz(v);break;}
      case 'start-boss':{const u=unitById[id];startSession(shuffled(bossPool(id)).slice(0,BOSS_SIZE),{type:'boss',unit:id,title:`Bosskampf · ${u.boss}`});break;}
      case 'exam-start':{const draft=state.examAttempts.find(a=>a.examId===id&&a.submittedAt===null);if(draft){go('exam/'+draft.id);break;}if(state.examAttempts.length>=100)throw new Error('Maximal 100 Klausurversuche. Exportiere deinen Stand, bevor du Platz durch einen Neustart schaffst.');const a=createAttempt(id,{minutes:Number(document.querySelector('#duration-'+id).value),previous:state.examAttempts});state.examAttempts.push(a);persist();go('exam/'+a.id);break;}
      case 'exam-jump':{const a=currentAttempt(),index=Number(button.dataset.index);if(a&&index>=0&&index<examById[a.examId].questions.length){a.index=index;persist();render();window.scrollTo({top:0,behavior:'instant'});}break;}
      case 'exam-flag':{const a=currentAttempt(),qid=examById[a.examId].questions[a.index].id;a.flags=a.flags.includes(qid)?a.flags.filter(x=>x!==qid):[...a.flags,qid];persist();render();break;}
      case 'exam-submit-review':{const a=currentAttempt(),exam=examById[a.examId],missing=exam.questions.filter(q=>!hasAnswer(a.answers[q.id])).length;document.querySelector('#exam-submit-panel').innerHTML=`<div class="feedback info"><strong>Bereit zur Abgabe?</strong>${missing} Aufgaben ohne Antwort · ${a.flags.length} markiert. Nach der Abgabe bleiben deine Antworten fest; dann erscheinen Lösungen und Bewertungsraster.<div class="inline-actions" style="margin-top:15px"><button class="btn" data-action="exam-submit">Jetzt verbindlich abgeben</button><button class="btn ghost" data-action="exam-cancel-submit">Weiterarbeiten</button></div></div>`;document.querySelector('#exam-submit-panel').scrollIntoView({block:'nearest'});break;}
      case 'exam-cancel-submit':document.querySelector('#exam-submit-panel').innerHTML='';break;
      case 'exam-submit':{const a=currentAttempt();if(submitAttempt(a)){announceBadges(updateBadges(state));persist();}render();window.scrollTo({top:0,behavior:'instant'});break;}
      case 'exam-print':window.print();break;
      case 'practice-start':startSession(selectPractice(state,practiceFilters),{title:practiceFilters.topic==='all'?'Deine gemischte Trainingsrunde':topicById[practiceFilters.topic].title});break;
      case 'topic-practice':startSession(selectPractice(state,{topic:id,count:5}),{title:topicById[id].title});break;
      case 'mission':{const m=missions.find(m=>m.id===id);startSession(selectPractice(state,{count:10},questions.filter(q=>m.topics.includes(q.lesson))),{title:'Mission: '+m.title});break;}
      case 'confidence':session.confidence=button.dataset.value;session.input=document.querySelector('#quiz-input')?.value||'';render();break;
      case 'review':startSession(dueQuestions(state).slice(0,15),{type:'review',title:'Deine fälligen Wiederholungen'});break;
      case 'retry-question':startSession([questionById[id]],{type:'review',title:'Aus einem Fehler lernen'});break;
      case 'lesson-quiz':startSession(selectPractice(state,{topic:id,count:8}),{type:'lesson',lesson:id,title:lessonById[id].title});break;
      case 'weekly-check':startSession(checkQuestions,{type:'check',title:'Wochencheck · Woche 1'});break;
      case 'select-answer':session.selected=Number(button.dataset.index);render();break;
      case 'submit-answer':submitAnswer();break;
      case 'skip':submitAnswer(true);break;
      case 'next-question':nextQuestion();break;
      case 'hint':session.input=document.querySelector('#quiz-input')?.value||'';session.hint=true;render();break;
      case 'save-note':state.notes[id]=document.querySelector('#lesson-note').value;if(persist())document.querySelector('#note-status').textContent='Deine Erklärung ist auf diesem Gerät gespeichert.';break;
      case 'save-error':state.errors[id].note=document.querySelector(`#error-note-${id}`).value;state.errors[id].rule=document.querySelector(`#error-rule-${id}`).value;if(persist())toast('Deine Fehlernotiz ist gespeichert.');break;
      case 'symbol':{const input=document.getElementById(button.dataset.target);if(input.disabled)break;const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(button.dataset.symbol,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();break;}
      case 'set-check':runSetLab(true);break;
      case 'set-solve':runSetLab(false);break;
      case 'regex-check':runRegexLab(true);break;
      case 'regex-preview':runRegexLab(false);break;
      case 'dfa-start':{const word=document.querySelector('#dfa-word').value.trim();if(/[^01]/.test(word)){document.querySelector('#dfa-stage').innerHTML='<div class="feedback error">Nur 0 und 1 sind erlaubt. Für ε lass das Feld leer.</div>';break;}dfaWord=word;dfaPosition=0;renderDfaStage();break;}
      case 'dfa-step':dfaPosition=Math.min(dfaPosition+1,dfaWord.length);renderDfaStage();break;
      case 'dfa-all':dfaPosition=dfaWord.length;renderDfaStage();break;
      case 'open-builder':builderKey=id;builderHelp=false;emptyBuilder();go('lab/builder');break;
      case 'builder-help':builderHelp=true;render();break;
      case 'builder-reset':builderHelp=false;emptyBuilder();render();break;
      case 'builder-check':checkBuilder();break;
      case 'focus':if(focus.remaining===0)focus.remaining=25*60;focus.running=!focus.running;focus.last=Date.now();updateFocusDisplay();break;
      case 'focus-reset':focus={remaining:25*60,running:false,last:Date.now(),unsaved:0};persist();updateFocusDisplay();break;
      case 'save-settings':{const dates=Object.fromEntries(subjects.map(sub=>[sub.id,document.querySelector(`#exam-date-${sub.id}`).value]));for(const sub of subjects){const value=dates[sub.id];if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||value<'2020-01-01'||value>'2100-12-31')throw new Error(`Wähle für ${sub.title} ein gültiges Datum zwischen 2020 und 2100.`);}state.goal=Number(document.querySelector('#goal').value);state.examDate=dates.ti;for(const sub of subjects)if(sub.id!=='ti')state.examDates[sub.id]=dates[sub.id];if(persist()){render();toast('Deine Lernziele sind gespeichert.');}break;}
      case 'export':exportProgress();break;
      case 'import':document.querySelector('#import-file').click();break;
      case 'cancel-import':pendingImport=null;document.querySelector('#import-preview').innerHTML='';break;
      case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;session=null;storageBlocked=false;storageNotice=null;persist();render();toast('Die Sicherung wurde übernommen.');}break;
      case 'reset':if(confirm('Deinen gesamten Orbit-Lernstand auf diesem Gerät zurücksetzen? Exportiere vorher eine Sicherung, wenn du ihn behalten möchtest.')){state=blankState();session=null;storageBlocked=false;storageNotice=null;focus={remaining:1500,running:false,last:Date.now(),unsaved:0};persist();render();toast('Dein Lernraum ist bereit für einen Neustart.');}break;
      case 'recover':if(confirm('Den unlesbaren Speicherstand nach eigener Sicherung durch den aktuell angezeigten Stand ersetzen?')){storageBlocked=false;storageNotice=null;persist();render();}break;
      case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;render();}break;
    }
  }catch(e){toast(e.message||'Das hat gerade nicht geklappt. Bitte versuche es erneut.');}
});
app.addEventListener('change',async event=>{
  const el=event.target;
  if(el.dataset.examAnswer&&el.type==='radio'){const a=currentAttempt();setExamAnswer(a,el.dataset.examAnswer,el.value);persist();render();}
  if(el.dataset.examRating){const a=currentAttempt();if(el.value!==''){rateCriterion(a,el.dataset.examRating,Number(el.dataset.criterion),Number(el.value));announceBadges(updateBadges(state));persist();const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});}else if(a.ratings[el.dataset.examRating]){a.ratings[el.dataset.examRating][Number(el.dataset.criterion)]=null;persist();render();}}
  if(el.dataset.practiceFilter){practiceFilters[el.dataset.practiceFilter]=el.value;if(el.dataset.practiceFilter==='topic'&&route()[1])go('practice');else render();}
  if(el.id==='dfa-machine'){dfaKey=el.value;dfaPosition=0;renderDfaStage();}
  if(el.id==='dfa-complement'){dfaComplement=el.checked;renderDfaStage();}
  if(el.id==='builder-task'){builderKey=el.value;builderHelp=false;emptyBuilder();render();}
  if(el.dataset.builderState)builderDraft.transitions[el.dataset.builderState][el.dataset.builderChar]=el.value;
  if(el.dataset.builderAccept){const s=el.dataset.builderAccept;builderDraft.accept=el.checked?[...new Set([...builderDraft.accept,s])]:builderDraft.accept.filter(x=>x!==s);}
  if(el.id==='import-file'){
    const file=el.files?.[0];if(!file)return;
    try{if(file.size>2*1024*1024)throw new Error('Diese Sicherung ist zu groß (maximal 2 MB).');pendingImport=validateImport(JSON.parse(await file.text()));const imported=stats(pendingImport);document.querySelector('#import-preview').innerHTML=`<div class="feedback info"><strong>Sicherung erkannt: ${imported.completed} Lektionen, ${imported.xp} XP</strong>Aktueller Stand: ${stats(state).completed} Lektionen, ${stats(state).xp} XP.<p>Beim Übernehmen wird dein aktueller Stand ersetzt.</p><div class="inline-actions" style="margin-top:15px"><button class="btn" data-action="confirm-import">Sicherung übernehmen</button><button class="btn ghost" data-action="cancel-import">Abbrechen</button></div></div>`;}catch(e){pendingImport=null;document.querySelector('#import-preview').innerHTML=`<div class="feedback error">${esc(e instanceof SyntaxError?'Die Datei enthält kein gültiges JSON. Dein Stand bleibt erhalten.':e.message)}</div>`;}el.value='';
  }
});
app.addEventListener('input',event=>{if(event.target.dataset.examAnswer&&event.target.type!=='radio'){const a=currentAttempt();setExamAnswer(a,event.target.dataset.examAnswer,event.target.value);const ok=persist(),el=document.querySelector('#exam-save-status');if(el)el.textContent=ok?'✓ Auf diesem Gerät gespeichert':'Speichern fehlgeschlagen – bitte exportieren';const i=examById[a.examId].questions.findIndex(q=>q.id===event.target.dataset.examAnswer),nav=document.querySelector(`[data-action="exam-jump"][data-index="${i}"]`);nav?.classList.toggle('answered',hasAnswer(event.target.value));} if(event.target.id==='growth-slider')renderGrowth();if(event.target.id==='quiz-input'&&session)session.input=event.target.value;});
app.addEventListener('keydown',event=>{
  if(event.key==='Enter'&&event.target.id==='quiz-input'){event.preventDefault();submitAnswer();}
  if(event.key==='Enter'&&event.target.id==='blitz-input'){event.preventDefault();const v=event.target.value.trim();if(v)answerBlitz(v);}
});
setInterval(()=>{
  const timer=document.querySelector('#exam-timer'),attempt=route()[0]==='exam'?currentAttempt():null;if(timer&&attempt){const remaining=remainingSeconds(attempt);timer.textContent=remaining===null?'Ohne Zeitlimit':remaining===0?'Trainingszeit abgelaufen':formatTime(remaining)+' verbleibend';}
  const now=Date.now();if(!focus.running||document.hidden){focus.last=now;return;}
  const seconds=Math.min(3,Math.floor((now-focus.last)/1000));if(seconds<=0)return;focus.last=now;
  const counted=Math.min(seconds,focus.remaining);focus.remaining-=counted;recordFocus(state,counted);focus.unsaved+=counted;
  if(focus.unsaved>=15){reward(()=>updateBadges(state));persist();focus.unsaved=0;}
  if(focus.remaining===0){focus.running=false;focus.unsaved=0;toast('25 Minuten geschafft. Zeit für eine kurze Pause.');reward(()=>updateBadges(state));persist();}
  updateFocusDisplay();
},1000);
document.addEventListener('visibilitychange',()=>{focus.last=Date.now();if(document.hidden&&focus.unsaved){persist();focus.unsaved=0;}});
window.addEventListener('pagehide',()=>{if(focus.unsaved)persist();});
document.addEventListener('keydown',event=>{
  if(route()[0]!=='cards'||!cardSession||cardSession.index>=cardSession.items.length||/INPUT|TEXTAREA|SELECT/.test(event.target.tagName))return;
  if(!cardSession.flipped&&(event.key===' '||event.key==='Enter')){event.preventDefault();cardSession.flipped=true;render();}
  else if(cardSession.flipped&&['1','2','3'].includes(event.key))rateCurrentCard(['again','hard','good'][Number(event.key)-1]);
});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#content')?.focus({preventScroll:true});});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
render();
